// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CaptureJob) predicate.CaptureJob {
	return predicate.CaptureJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CaptureJob) predicate.CaptureJob {
	return predicate.CaptureJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CaptureJob) predicate.CaptureJob {
	return predicate.CaptureJob(sql.NotPredicates(p))
}





